}

// ResolveHarnessAlias returns the canonical harness name for an alias,
// or the input unchanged if it is not an alias.
func ResolveHarnessAlias(name string) string {
	if canonical, ok := harnessAliases[name]; ok {
		return canonical
	}
	return name
}

